SELECT CASE WHEN d.budget >= 3547000 THEN 'high' WHEN d.budget >= 1819000 THEN 'mid' ELSE 'low' END AS budget_bucket, d.location, SUM(e.salary) AS total_salary FROM employees e RIGHT OUTER JOIN departments d ON e.dept_id = d.id GROUP BY CASE WHEN d.budget >= 3547000 THEN 'high' WHEN d.budget >= 1819000 THEN 'mid' ELSE 'low' END, d.location HAVING total_salary > 740000 ORDER BY 1 ASC, location ASC LIMIT 50
